from pathlib import Path
import re
p = Path('CashLender-Supabase-Netlify/index.html')
s = p.read_text()
style = r'''  <style id="pin-security-styles">
#authGate{position:fixed;inset:0;z-index:10000;display:flex;align-items:center;justify-content:center;padding:18px;overflow:hidden;isolation:isolate;background:radial-gradient(ellipse at 15% 12%,rgba(48,132,129,.32),transparent 38%),radial-gradient(ellipse at 88% 82%,rgba(18,88,92,.34),transparent 36%),linear-gradient(135deg,#07151f,#0d2a34 48%,#071923)}
#authGate:before{content:"";position:absolute;inset:0;z-index:-1;opacity:.2;background-image:linear-gradient(rgba(185,218,211,.1) 1px,transparent 1px),linear-gradient(90deg,rgba(185,218,211,.08) 1px,transparent 1px);background-size:44px 44px}
#authGate.hidden,#changePinModal.hidden,#appShell.hidden{display:none!important}
.pin-panel{position:relative;width:min(100%,540px);min-height:590px;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:38px clamp(22px,6vw,56px);overflow:hidden;text-align:center;border:1px solid rgba(210,238,232,.24);border-radius:32px;background:linear-gradient(145deg,rgba(28,63,70,.9),rgba(8,27,39,.95) 56%,rgba(15,45,53,.92));box-shadow:0 34px 100px rgba(0,0,0,.56),inset 0 1px 0 rgba(255,255,255,.18);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px)}
.pin-brand{position:relative;z-index:1;margin-bottom:28px}.pin-wordmark{display:block;font-family:'Manrope','DM Sans',sans-serif;font-size:clamp(3.8rem,11vw,5.5rem);line-height:.94;font-weight:800;letter-spacing:-.085em;background:linear-gradient(180deg,#fff8d7 2%,#c9c5b5 26%,#f2e4ba 48%,#8f9b9a 70%,#f0e6d0 92%);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent;filter:drop-shadow(0 4px 2px rgba(0,0,0,.5))}.pin-brand-sub{margin-top:12px;color:#e2d4ad;font-size:12px;font-weight:700;letter-spacing:.23em;text-transform:uppercase}
#loginTitle{position:relative;z-index:1;margin:0 0 9px;color:#f6f8f8;font-family:'Manrope','DM Sans',sans-serif;font-size:clamp(1.8rem,6vw,2.3rem);font-weight:800;letter-spacing:-.05em}.pin-subtitle{position:relative;z-index:1;color:rgba(214,231,229,.72);font-size:14px;margin-bottom:23px}
.pin-visual{position:relative;width:100%;height:132px;overflow:hidden;margin:0 0 20px;border-radius:25px;border:1px solid rgba(202,231,226,.2);background:linear-gradient(110deg,rgba(4,20,29,.8),rgba(9,37,45,.75));box-shadow:inset 0 8px 28px rgba(0,0,0,.34),0 12px 32px rgba(0,0,0,.2)}.pin-network{position:absolute;inset:0;width:100%;height:100%}.pin-network .route{stroke:rgba(223,210,166,.74);stroke-width:1.7;fill:none}.pin-network .node{fill:#e8d5a1;stroke:#fff4ca;stroke-width:1.4;filter:drop-shadow(0 0 5px rgba(236,215,159,.8))}.pin-network .teal{fill:#50e3d0;stroke:#b8fff4;filter:drop-shadow(0 0 7px rgba(63,235,220,.95))}.pin-network .pulse{animation:pinPulse 2.5s ease-in-out infinite;transform-origin:center}.pin-network .pulse:nth-of-type(2n){animation-delay:.6s}.pin-fingerprint{position:absolute;left:50%;top:50%;width:40px;height:46px;transform:translate(-50%,-50%);opacity:.3}
.pin-input{width:100%;min-height:56px!important;border:1px solid rgba(220,234,220,.36)!important;border-radius:14px!important;background:rgba(3,17,25,.72)!important;color:#fff6d7!important;text-align:center;font-size:24px!important;font-weight:800!important;letter-spacing:.55em!important;padding:12px 18px 12px 26px!important;outline:none!important;box-shadow:inset 0 2px 10px rgba(0,0,0,.36)!important}.pin-input::placeholder{color:rgba(237,229,197,.56);letter-spacing:.45em}.pin-primary{display:block;width:100%;border:1px solid rgba(255,239,192,.62);border-radius:13px;background:linear-gradient(115deg,#d7bb7b,#f5e6b7 48%,#c5a66b);color:#17252b;font-weight:850;padding:13px 18px;cursor:pointer;box-shadow:0 10px 26px rgba(0,0,0,.25)}.pin-primary:hover{filter:brightness(1.08);transform:translateY(-1px)}
#loginForm{width:100%;max-width:310px;display:flex;flex-direction:column;align-items:stretch;gap:14px}#loginForm>*{margin-top:0!important}#loginError{color:#ffc3bb!important;position:relative;z-index:2}.pin-security-note{margin-top:23px;color:rgba(207,224,222,.52);font-size:11px;line-height:1.6}#changePinModal{position:fixed;inset:0;z-index:9999;display:flex;align-items:center;justify-content:center;padding:18px;background:rgba(8,21,32,.68);backdrop-filter:blur(5px)}.pin-modal{width:min(100%,460px);background:#fff;border-radius:22px;padding:24px;box-shadow:0 25px 80px rgba(0,0,0,.28)}.pin-secondary{border:1px solid #d7e1e5;border-radius:11px;padding:10px 14px;background:#fff;color:#334155;font-weight:700;cursor:pointer}#appShell>header h1 span:first-child{color:#facc15!important}
@keyframes pinPulse{0%,100%{opacity:.72;transform:scale(.88)}50%{opacity:1;transform:scale(1.18)}}@media(max-width:560px){#authGate{padding:12px}.pin-panel{min-height:min(660px,calc(100dvh - 24px));padding:30px 19px 25px;border-radius:26px}.pin-visual{height:118px}.pin-security-note{margin-top:19px}}@media(prefers-reduced-motion:reduce){.pin-network .pulse{animation:none}}
  </style>'''
s, n = re.subn(r'  <style id="pin-security-styles">.*?</style>', style, s, count=1, flags=re.S)
if n != 1: raise SystemExit(f'PIN style block count {n}')
s = s.replace('<div class="pin-mark">S</div>', '<div class="pin-brand"><span class="pin-wordmark">Sibi</span><p class="pin-brand-sub">Financial Portfolio</p></div>')
s = s.replace('<p class="text-xs font-extrabold tracking-[.22em] text-emerald-700 mb-2">SIBI FINANCIAL ACCOUNT</p>', '')
s = s.replace('<p class="text-sm text-slate-500 mb-6">Unlock your shared family ledger.</p>', '<p class="pin-subtitle">Secure access to your financial portfolio.</p>')
s = s.replace('Unlock Ledger', 'Unlock Portfolio')
visual = r'''      <div class="pin-visual" aria-hidden="true"><svg class="pin-network" viewBox="0 0 520 140" preserveAspectRatio="xMidYMid meet"><path class="route" d="M42 76 L118 42 L178 91 L244 104 L292 76 L354 38 L420 75 L478 47"/><path class="route" d="M118 42 L154 116 L244 104 L292 76 L334 111 L420 75"/><path class="route" d="M178 91 L218 52 L292 76 L354 38"/><circle class="node pulse" cx="42" cy="76" r="5"/><circle class="node teal pulse" cx="118" cy="42" r="6"/><circle class="node pulse" cx="178" cy="91" r="5"/><circle class="node teal pulse" cx="244" cy="104" r="6"/><circle class="node pulse" cx="292" cy="76" r="5"/><circle class="node pulse" cx="354" cy="38" r="6"/><circle class="node teal pulse" cx="420" cy="75" r="6"/><circle class="node pulse" cx="478" cy="47" r="5"/><circle class="node pulse" cx="154" cy="116" r="4"/><circle class="node teal pulse" cx="218" cy="52" r="4"/><circle class="node pulse" cx="334" cy="111" r="4"/></svg><svg class="pin-fingerprint" viewBox="0 0 48 56" fill="none" stroke="#d7e5d8" stroke-width="1.45" stroke-linecap="round"><path d="M24 5C13 5 6 13 6 24M24 11c-7 0-12 5-12 12 0 8-2 14-5 19M24 17c-4 0-6 3-6 7 0 11-2 18-5 24M24 5c11 0 18 8 18 19 0 9-2 17-6 23M24 11c7 0 12 5 12 13 0 9-1 15-4 22M24 23v8c0 8-1 13-3 18M17 27c0 8-1 13-4 18M31 27c0 7-1 13-3 18"/></svg></div>
'''
needle = '      <form id="loginForm" class="space-y-4">'
if needle not in s: raise SystemExit('login form marker not found')
s = s.replace(needle, visual + needle, 1)
p.write_text(s)
print('Applied Sibi portfolio PIN design')
